{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Rilzabrutinib, which shares the same pyrazolo[3,4-d]pyrimidine, 4-phenoxyphenyl, and piperidine-acrylamide core as the query, had an absolute oral bioavailability of only 6.4% in healthy subjects, directly supporting F<20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib, a related covalent BTK inhibitor with a different heteroaromatic core, achieved 25.3% absolute oral bioavailability in humans, showing that the class is not inherently below 20%, but its lower structural similarity to the query limits transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is ibrutinib, a covalent BTK inhibitor. The closest high-transfer analog rilzabrutinib, sharing the identical pyrazolopyrimidine-phenoxyphenyl-piperidine acrylamide core, has absolute oral bioavailability of only ~5% in humans. This direct, threshold-relevant evidence outweighs the mixed physicochemical prior and the higher F of more distantly related BTK inhibitors, so the query is predicted to have F<20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for the query itself is included in the supplied evidence; the closest analog rilzabrutinib has a bulky basic side chain absent in the query, so transferability is not perfect.",
    "Acalabrutinib demonstrates that some BTK inhibitors can exceed 20% F, but its lower similarity leaves some uncertainty about whether the shared core alone dictates low F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

